from rdkit import Chem
import numpy as np
m=Chem.MolFromMolFile('model.mol',removeHs=False)
l=open('optimized.xyz').read().splitlines();x=np.array([[float(q) for q in s.split()[1:]] for s in l[2:101]])
for a in m.GetAtoms():
 m.GetConformer().SetAtomPosition(a.GetIdx(),x[a.GetIdx()])
Chem.AssignAtomChiralTagsFromStructure(m,replaceExistingTags=True)
Chem.AssignStereochemistry(m,cleanIt=True,force=True)
print('CIP', m.GetAtomWithIdx(27).GetPropsAsDict())
print('Metal distances:')
for j in range(44):
 if j!=0 and np.linalg.norm(x[j]-x[0])<3.4: print(j,l[j+2].split()[0],np.linalg.norm(x[j]-x[0]))
print('bond check:')
for b in m.GetBonds():
 i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx();d=np.linalg.norm(x[i]-x[j]);
 if (d>1.75 and i!=0 and j!=0 and i!=8 and j!=8) or d<.85:print(i,j,d)
Chem.MolToMolFile(m,'opt.mol')
PY
